param([Parameter(Mandatory=$true)][string]$SourceScript)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;Add-Type -AssemblyName System.Security
$parent=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\');$root=Join-Path $parent ('devsetu-software-consent-'+[guid]::NewGuid().ToString('N'));$local=Join-Path $root 'local';$id='fc_'+[guid]::NewGuid().ToString('N');$directory=Join-Path $local ('FrevOS\Connector\'+$id);$state=Join-Path $directory 'state';[void][IO.Directory]::CreateDirectory($state)
function Hash($p){(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()}
try{
 $file=Join-Path $directory 'device.dpapi';$config=@{mode='system';deviceId=$id;server='https://synthetic.invalid';accountName='pair:synthetic-only';stateRoot=$state;credential='synthetic-not-a-live-credential'};$plain=[Text.UTF8Encoding]::new($false).GetBytes(($config|ConvertTo-Json -Compress));try{[IO.File]::WriteAllBytes($file,[Security.Cryptography.ProtectedData]::Protect($plain,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser))}finally{[Array]::Clear($plain,0,$plain.Length);$config=$null}
 $before=Hash $file;$acl=(Get-Acl -LiteralPath $file).Sddl
 function InvokeConsent($inventory,$install,$server){$inputValue=@{deviceId=$id;server=$server;username='pair:synthetic-only';inventory=$inventory;install=$install};$start=[Diagnostics.ProcessStartInfo]::new();$start.FileName=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe';$start.Arguments='-NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File "'+$SourceScript+'"';$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;$start.EnvironmentVariables['LOCALAPPDATA']=$local;$start.EnvironmentVariables['PSModulePath']=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\Modules';$process=[Diagnostics.Process]::new();$process.StartInfo=$start;try{[void]$process.Start();$output=$process.StandardOutput.ReadToEndAsync();$errorOutput=$process.StandardError.ReadToEndAsync();$process.StandardInput.Write(($inputValue|ConvertTo-Json -Compress));$process.StandardInput.Close();if(-not $process.WaitForExit(15000)){$process.Kill();throw 'Fixture helper deadline'};[void]$errorOutput.Result;return @{exitCode=$process.ExitCode;output=$output.Result;error=$errorOutput.Result}}finally{$process.Dispose()}}
 $enabled=InvokeConsent $true $true 'https://synthetic.invalid';$consentFile=Join-Path $state 'software\consent.json';$consent=Get-Content -LiteralPath $consentFile -Raw|ConvertFrom-Json;if($enabled.exitCode -ne 0 -or -not $consent.install -or -not $consent.inventory){throw 'Local opt-in did not persist'}
 $disabled=InvokeConsent $false $false 'https://synthetic.invalid';$consent=Get-Content -LiteralPath $consentFile -Raw|ConvertFrom-Json;if($disabled.exitCode -ne 0 -or $consent.install -or $consent.inventory){throw 'Local opt-out did not persist'}
 $saved=Hash $consentFile;$denied=InvokeConsent $true $true 'https://other.invalid';if($denied.exitCode -eq 0 -or (Hash $consentFile) -cne $saved -or (Hash $file) -cne $before -or (Get-Acl -LiteralPath $file).Sddl -cne $acl){throw 'Consent crossed pairing boundary'}
