}finally{$resolved=[IO.Path]::GetFullPath($root);if([IO.Path]::GetDirectoryName($resolved) -cne $parent -or [IO.Path]::GetFileName($resolved) -cnotmatch '^devsetu-software-consent-[a-f0-9]{32}$'){throw 'Fixture cleanup scope differs'};Remove-Item -LiteralPath $resolved -Recurse -Force}
